package dk.stream.android;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
public class PlaybackJournalTest {
 private static class Store implements PlaybackJournal.Store{final Map<String,String> values=new HashMap<>();int writes;public String get(String key){return values.containsKey(key)?values.get(key):"";}public void put(String key,String value){values.put(key,value);writes++;}public void clear(){values.clear();}}
 @Test public void positionsSurviveRestartAndKeepMediaIndependent(){Store store=new Store();PlaybackJournal journal=new PlaybackJournal(store);journal.record("content://local/one",12000,100000,false,true,0);journal.record("https://example.com/film",34000,200000,false,true,0);PlaybackJournal restarted=new PlaybackJournal(store);assertEquals(12000,restarted.get("content://local/one").resume());assertEquals(34000,restarted.get("https://example.com/film").resume());assertEquals(120,restarted.get("content://local/one").progress());}
 @Test public void clearRemovesStoredAndCachedPositions(){Store store=new Store();PlaybackJournal journal=new PlaybackJournal(store);journal.record("one",100,1000,false,true,0);journal.record("two",1000,1000,true,true,0);journal.clear();assertTrue(store.values.isEmpty());assertEquals(0,journal.get("one").duration);assertEquals(0,journal.get("two").progress());assertEquals(0,new PlaybackJournal(store).get("one").resume());}
 @Test public void activePositionUpdatesImmediatelyButDiskWritesAreThrottled(){Store store=new Store();PlaybackJournal journal=new PlaybackJournal(store);journal.record("one",1000,100000,false,false,0);journal.record("one",2000,100000,false,false,1000);assertEquals(2000,journal.get("one").resume());assertEquals(1,store.writes);journal.record("one",2200,100000,false,true,1200);assertEquals(2,store.writes);assertEquals(2200,new PlaybackJournal(store).get("one").resume());}
 @Test public void completedStateSurvivesRestart(){Store store=new Store();PlaybackJournal journal=new PlaybackJournal(store);journal.record("film",100000,100000,true,true,0);PlaybackMark mark=new PlaybackJournal(store).get("film");assertEquals(1000,mark.progress());assertEquals(0,mark.resume());}
 @Test public void invalidOrUnknownDurationDoesNotEraseSavedProgress(){Store store=new Store();PlaybackJournal journal=new PlaybackJournal(store);journal.record("one",12000,100000,false,true,0);journal.record("one",0,-1,false,true,1000);assertEquals(12000,journal.get("one").resume());}
 @Test public void storedKeysDoNotExposePrivateFileUrls(){Store store=new Store();PlaybackJournal journal=new PlaybackJournal(store);journal.record("https://example.com/private/password.mp4",10,100,false,true,0);assertEquals(64,store.values.keySet().iterator().next().length());assertFalse(store.values.keySet().iterator().next().contains("password"));}
}
